SELECT TOP (1) @DonViPheDuyet = [Id] FROM [dm].[DanhMucDonVis] WHERE [Id] <> '00000000-0000-0000-0000-000000000000' AND [Id] <> @DonViSoanThao ORDER BY [CreatedDate], [Id];
SET @DonViPheDuyet = COALESCE(@DonViPheDuyet, @DonViSoanThao);
